  "story.core.value1": {
    "vi": "1. THẦN TỐC – “Nhanh là sống, chậm là chết”…",
    "en": "1. SPEED – “Fast is life, slow is death”…",
    "ko": "1. SPEED – “빠른 것은 삶이고 느린 것은 죽음이다”…",
    "zh": "1. 速度——“快则生，慢则死”……",
    "ru": "1. СКОРОСТЬ – «Жизнь быстрая, смерть медленная»…",
    "hi": "1. गति - \"तेज़ जीवन है, धीमी मृत्यु है\"..."
  },
  "story.core.value2": {
    "vi": "2. TẬN TÂM – “Làm gì cũng phải làm đến nơi đến chốn”…",
    "en": "2. Dedication – “Whatever you do, do it to the end”…",
    "ko": "2. 헌신 - “무엇을 하든지 끝까지 하라”…",
    "zh": "2. 奉献——“无论做什么，都要坚持到底”……",
    "ru": "2. Преданность – «Что бы ты ни делал, делай это до конца»…",
    "hi": "2. समर्पण - \"आप जो भी करें, अंत तक करें\"..."
  },
  "story.core.value3": {
    "vi": "3. TỬ TẾ – “Muốn đi xa, phải đi cùng người tử tế”…",
    "en": "3. KINDNESS – “If you want to go far, go with kind people”…",
    "ko": "3. KINDNESS – “멀리 가려면 친절한 사람과 함께 가라”…",
    "zh": "3. 善良——“如果你想走得远，就和善良的人一起走”……",
    "ru": "3. ДОБРОТА – «Если хочешь идти далеко, иди с добрыми людьми»…",
    "hi": "3. दयालुता - \"यदि आप दूर तक जाना चाहते हैं, तो दयालु लोगों के साथ जाएं\"..."
  },
  "story.core.figure.caption": {
    "vi": "Hành trình của Anstay là hành trình của những con người tin vào sự khác biệt và sống bằng đam mê phụng sự.",
    "en": "Anstay's journey is the journey of people who believe in difference and live by passion for service.",
    "ko": "안스테이의 여정은 다름을 믿고 봉사에 대한 열정으로 살아가는 사람들의 여정입니다.",
    "zh": "Anstay 的旅程是那些相信差异并以服务热情为生的人们的旅程。",
    "ru": "Путь Anstay — это путь людей, которые верят в различия и живут страстью к служению.",
    "hi": "एंस्टे की यात्रा उन लोगों की यात्रा है जो अंतर में विश्वास करते हैं और सेवा के जुनून से जीते हैं।"
  },
